import { lstat, mkdir, readFile, realpath, writeFile } from "node:fs/promises";
import { dirname, relative, resolve, sep } from "node:path";

const workspaceRoot = resolve(import.meta.dirname, "..");
const sourceRoot = resolve(
  workspaceRoot,
  "vendor",
  "tauri-plugin-wdio-webdriver",
);
const outputRoot = resolve(
  workspaceRoot,
  "dist",
  "provider",
  "tauri-plugin-wdio-webdriver",
);

// Keep this list deliberately explicit. In particular, never walk the vendor
// tree: it contains Cargo target output and other material which must not be
// published or copied into a consumer project.
export const PROVIDER_SOURCE_ALLOWLIST = [
  "build.rs",
  "Cargo.toml",
  "LICENSE",
  "PATCHES.md",
  "permissions/autogenerated/commands/request_dialog.toml",
  "permissions/autogenerated/reference.md",
  "permissions/default.toml",
  "permissions/schemas/schema.json",
  "README.md",
  "src/desktop.rs",
  "src/dialog.rs",
  "src/error.rs",
  "src/lib.rs",
  "src/mobile.rs",
  "src/platform/alert_state.rs",
  "src/platform/android.rs",
  "src/platform/executor.rs",
  "src/platform/ios.rs",
  "src/platform/linux.rs",
  "src/platform/macos.rs",
  "src/platform/mod.rs",
  "src/platform/windows.rs",
  "src/server/handlers/actions.rs",
  "src/server/handlers/alert.rs",
  "src/server/handlers/cookie.rs",
  "src/server/handlers/direct_eval.rs",
  "src/server/handlers/document.rs",
  "src/server/handlers/element.rs",
  "src/server/handlers/frame.rs",
  "src/server/handlers/mod.rs",
  "src/server/handlers/navigation.rs",
  "src/server/handlers/print.rs",
  "src/server/handlers/screenshot.rs",
  "src/server/handlers/script.rs",
  "src/server/handlers/session.rs",
  "src/server/handlers/shadow.rs",
  "src/server/handlers/tauri_dialog.rs",
  "src/server/handlers/timeouts.rs",
  "src/server/handlers/window.rs",
  "src/server/mod.rs",
  "src/server/response.rs",
  "src/server/router.rs",
  "src/webdriver/element.rs",
  "src/webdriver/locator.rs",
  "src/webdriver/mod.rs",
  "src/webdriver/session.rs",
].toSorted();

function safeTarget(root, path) {
  const candidate = resolve(root, path);
  const difference = relative(root, candidate);
  if (
    difference === "" ||
    difference === ".." ||
    difference.startsWith(`..${sep}`) ||
    resolve(root, difference) !== candidate
  ) {
    throw new Error(`Provider bundle path escapes its root: ${path}`);
  }
  return candidate;
}

function sameCanonicalPath(left, right) {
  const normalize = (value) => {
    const resolved = resolve(value);
    return process.platform === "win32" ? resolved.toLowerCase() : resolved;
  };
  return normalize(left) === normalize(right);
}

async function validateSourceRoot() {
  const metadata = await lstat(sourceRoot);
  if (!metadata.isDirectory() || metadata.isSymbolicLink()) {
    throw new Error(
      "Provider bundle source root is not a canonical directory.",
    );
  }
  const canonicalRoot = await realpath(sourceRoot);
  if (!sameCanonicalPath(canonicalRoot, sourceRoot)) {
    throw new Error(
      "Provider bundle source root must not use a linked ancestor.",
    );
  }
  return canonicalRoot;
}

async function validateSourceFile(canonicalRoot, sourceRelativePath) {
  const sourcePath = safeTarget(canonicalRoot, sourceRelativePath);
  const metadata = await lstat(sourcePath);
  if (metadata.isSymbolicLink() || !metadata.isFile()) {
    throw new Error(
      `Provider bundle entry is not a regular file: ${sourceRelativePath}`,
    );
  }
  const canonicalPath = await realpath(sourcePath);
  if (!sameCanonicalPath(canonicalPath, sourcePath)) {
    throw new Error(
      `Provider bundle entry is not under the canonical source root: ${sourceRelativePath}`,
    );
  }
  return sourcePath;
}

const canonicalSourceRoot = await validateSourceRoot();
const validatedSources = await Promise.all(
  PROVIDER_SOURCE_ALLOWLIST.map(async (sourceRelativePath) => ({
    sourceRelativePath,
    sourcePath: await validateSourceFile(
      canonicalSourceRoot,
      sourceRelativePath,
    ),
  })),
);

await mkdir(outputRoot, { recursive: true });
for (const { sourceRelativePath, sourcePath } of validatedSources) {
  const outputPath = safeTarget(outputRoot, sourceRelativePath);
  // Ship LF, the form Git stores, whatever the build checkout uses.
  const content = (await readFile(sourcePath, "utf8")).replaceAll("\r\n", "\n");
  await mkdir(dirname(outputPath), { recursive: true });
  await writeFile(outputPath, content);
}
